function smartData(property){if(smartCache.has(property.id))return smartCache.get(property.id);if(!property.coordinates){const result={pulse:null,nearby:[],safety:localitySafety(property.area,{market:property.market})};smartCache.set(property.id,result);return result;}const pulse=activityPulse(property.coordinates,places,{radius:1000,market:property.market}),highlights=activityHighlights(property.coordinates,places,{radius:2500}),wanted=[['swimming','Swim'],['gyms','Gym'],['sports','Sport'],['shopping','Daily'],['restaurants','Food']];const nearby=wanted.flatMap(([category,label])=>{const hit=highlights.find(place=>place.category===category);return hit?[{label,name:hit.name,distance:distanceLabel(hit.distance)}]:[];}).slice(0,2),result={pulse,nearby,safety:localitySafety(property.area,{market:property.market})};smartCache.set(property.id,result);return result;}
