function renderListingRow(title,items,index){const cards=items.slice(0,14);if(!cards.length)return '';return `<section class="listing-row" aria-labelledby="listing-row-${index}"><div class="listing-row-head"><div><h3 id="listing-row-${index}">${escapeHTML(title)}</h3><span>${cards.length}${items.length>cards.length?'+':''} homes</span></div><div class="row-arrows"><button type="button" data-row-scroll="-1" aria-label="Scroll ${escapeHTML(title)} left">←</button><button type="button" data-row-scroll="1" aria-label="Scroll ${escapeHTML(title)} right">→</button></div></div><div class="listing-rail" tabindex="0">${cards.map(renderCard).join('')}</div></section>`;}
function bindRails(){
 document.querySelectorAll('.listing-rail').forEach(rail=>{
  let lastWheel=0;let entered=0,startX=0,peakX=0,startY=0,hovering=false,released=false,rightIntent=false;
  const reset=()=>{lastWheel=0;hovering=false;entered=0;released=false;rightIntent=false;rail.classList.remove('is-wheel-active');};
  rail.addEventListener('pointerenter',event=>{if(event.pointerType!=='mouse')return;hovering=true;entered=performance.now();startX=peakX=event.clientX;startY=event.clientY;released=false;rightIntent=false;});
  rail.addEventListener('pointermove',event=>{
   if(!hovering||event.pointerType!=='mouse')return;
   if(peakX-event.clientX>=14||Math.abs(event.clientY-startY)>12){released=true;rightIntent=false;startX=peakX=event.clientX;startY=event.clientY;entered=performance.now();rail.classList.remove('is-wheel-active');return;}
   peakX=Math.max(peakX,event.clientX);
   if(event.clientX-startX>=24){rightIntent=true;released=false;}
  });
  rail.addEventListener('pointerleave',reset);
  rail.addEventListener('pointercancel',reset);
  rail.addEventListener('wheel',event=>{
   if(event.ctrlKey||event.metaKey||event.shiftKey||!hovering||released||Math.abs(event.deltaY)<=Math.abs(event.deltaX)||rail.scrollWidth<=rail.clientWidth)return;
   if(!event.target.closest('.listing-card'))return;
   const now=performance.now(),age=now-entered;if(lastWheel&&now-lastWheel>650){entered=now;rightIntent=false;lastWheel=0;rail.classList.remove('is-wheel-active');return;}
   if(!(rightIntent&&age>=500||age>=750)){
    // Continuing to scroll down is not a request to capture a stationary cursor.
    if(!rightIntent)entered=performance.now();return;
   }
   const delta=event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?rail.clientWidth:1);
   if(rail.scrollLeft<=1&&delta<0||rail.scrollLeft+rail.clientWidth>=rail.scrollWidth-1&&delta>0){reset();return;}
   lastWheel=now;event.preventDefault();rail.classList.add('is-wheel-active');rail.scrollBy({left:delta*.9,behavior:'instant'});
  },{passive:false});
 });
}
function render(){const grid=$('#market-grid'),rows=diversifyRows(rowDefinitions().map(([title,select])=>({title,items:select(visible)}))).map(({title,items},index)=>renderListingRow(title,items,index)).filter(Boolean);grid.innerHTML=villageStrip()+rows.join('');bindRails();$('#skeleton-grid').hidden=true;grid.hidden=false;$('#load-more').hidden=true;$('#result-meta').textContent=`${visible.length} live ${MARKET_LABELS[applied.market].toLowerCase()} ${visible.length===1?'listing':'listings'} · refreshed from 2906 · aesthetic views first`;$('#result-kicker').textContent=`LIVE ${MARKET_LABELS[applied.market].toUpperCase()}`;$('#result-title').textContent=visible.length?'Browse homes':'No homes match these filters yet.';renderActiveFilters();}
function renderActiveFilters(){const values=[MARKET_LABELS[applied.market],applied.place,applied.beds?`${applied.beds}+ beds`:'',applied.budget?`Up to ${currency(applied.budget)}`:'',applied.available!=='any'?(applied.available==='now'?'Move now':`Within ${applied.available} days`):'',applied.query?`“${applied.query}”`:'' ].filter(Boolean);$('#active-filters').innerHTML=values.map(value=>`<span>${escapeHTML(value)}</span>`).join('');}
function markDirty(){const dirty=JSON.stringify(draft)!==JSON.stringify(applied);$('#filter-state').classList.toggle('is-dirty',dirty);$('#filter-state span').textContent=dirty?'Filters changed. Press Show homes to apply.':'Showing applied filters.';}
function syncControls(){$('#query').value=draft.query;$('#place').value=draft.place;$('#beds').value=String(draft.beds);$('#budget').value=String(draft.budget);$$('[data-market]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.market===draft.market)));$$('[data-available]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.available===draft.available)));markDirty();}
function setMarket(market){draft=defaults();draft.market=market;applied={...draft};syncControls();filterInventory();}
function propertyIntelligenceTitle(property){const title=String(property.title||'').replace(/^\s*\d+[\s-]*(?:bed(?:room)?s?)\s*/i,'').trim();return title||`${property.propertyType} in ${property.area}`;}
function connectorByKey(intelligence,key){return intelligence.connectors.find(connector=>connector.key===key)||intelligence.connectors[0];}
function boltForPlace(place){const roadMetres=Number(place.drivingDistanceMetres??place.roadDistanceMetres),minutes=Number.isFinite(place.drivingSeconds)?place.drivingSeconds/60:Number(place.drivingMinutes);if(!place.routeVerified||!Number.isFinite(roadMetres)||roadMetres<=0)return {label:'Bolt UNKNOWN',detail:'road route required'};const estimate=estimateBoltReference({roadKm:roadMetres/1000,journeyMinutes:minutes,origin:activeProperty?.area||'',destination:place.name,observations:mobilityObservations});if(!Number.isFinite(estimate.expected))return {label:'Bolt UNKNOWN',detail:'no comparable observation'};const format=value=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:1}).format(value),range=Number.isFinite(estimate.low)&&Number.isFinite(estimate.high)?` · observed ${format(estimate.low)}–${format(estimate.high)}`:'';return {label:`Bolt ≈ ${format(estimate.expected)}`,detail:`${estimate.confidence} · ${estimate.count} reference${estimate.count===1?'':'s'}${range}`};}
function placeDistanceEvidence(place){const precision=$('#property-drawer')?.__intelligence?.precision;if(precision==='AREA_ONLY'){const rounded=Math.max(100,Math.round(Number(place.distance||0)/100)*100);return `around this area · approx. ${distanceLabel(rounded)}`;}if(precision==='APPROXIMATE'){const rounded=Math.max(50,Math.round(Number(place.distance||0)/50)*50);return `approx. ${distanceLabel(rounded)} straight line`;}return `${distanceLabel(place.distance)} straight line`;}
function renderPlaceEvidence(place){const travel=placeTravelEvidence(place),bolt=boltForPlace(place),loading=$('#property-drawer').__routingState==='loading',walk=travel.walk==='UNKNOWN'?(loading?'Calculating…':'Walk unavailable'):`${travel.walk} walk`,drive=travel.drive==='UNKNOWN'?'':`${travel.drive} drive`,walkDistance=Number.isFinite(place.walkingDistanceMetres)?` · ${(place.walkingDistanceMetres/1000).toFixed(2)+' km'} on foot`:'',price=bolt.label==='Bolt UNKNOWN'?'Bolt estimate unavailable':bolt.label;return `<button type="button" class="connector-place" data-map-place="${escapeHTML(place.id)}"><span><b>${escapeHTML(place.name)}</b><small>${escapeHTML(place.kind||place.category)} · ${escapeHTML(placeDistanceEvidence(place))}</small><small>${place.routeVerified?'MODELLED · '+($('#property-drawer').__intelligence.precision==='AREA_ONLY'?'from area anchor · ':'')+'no live traffic':''}</small></span><span><b>${escapeHTML(walk)}</b><small>${escapeHTML(drive+walkDistance)}</small><small>${escapeHTML(price)}${bolt.label!=='Bolt UNKNOWN'?' · estimate':''}</small></span></button>`;}
