  if(result.status!=='CONNECTED')throw Error('ROUTING_UNAVAILABLE');
  const routes=new Map(result.places.map(item=>[item.id,item])),mapped={...property,coordinates:result.publicCoordinates||property.coordinates,locationDisclosure:result.precision};
