  const key=$('.intelligence-map').dataset.activeConnector;activateConnector(key);await mountPropertyMap(intelligence);
  $('[data-route-status]').textContent=`${result.places.filter(p=>p.routeVerified).length} connections calculated`;
  $('.property-anchor-label').textContent=result.precision==='AREA_ONLY'?'AROUND THIS AREA':'APPROXIMATE HOME LOCATION';
