  const nearest=connector.places.slice(0,2),routes=connector.places.filter(p=>p.routeVerified),best=routes.find(p=>Number.isFinite(p.walkingSeconds)),minutes=best?Math.max(1,Math.round(best.walkingSeconds/60)):null;
  return `<article class="life-stat" style="--stat-hue:${{swimming:185,daily:40,social:15,wellbeing:145,mobility:215}[connector.key]}"><div class="life-stat-head"><i class="stat-star">${icons[connector.key]}</i><span>${escapeHTML(connector.label)}</span><button type="button" data-insight-connector="${connector.key}" aria-label="Explore ${escapeHTML(connector.label)}">↗</button></div><div class="life-stat-number">${minutes!==null?`<b>${minutes}</b><span>min walk<small>nearest routed option</small></span>`:`<b>${connector.places.length}</b><span>places<small>in the mapped area</small></span>`}</div><div class="life-stat-places">${nearest.length?nearest.map(place=>{const travel=placeTravelEvidence(place),km=Number.isFinite(place.walkingDistanceMetres)?(place.walkingDistanceMetres/1000).toFixed(2)+' km walk':(place.distance/1000).toFixed(1)+' km straight line';return `<button type="button" data-insight-place="${escapeHTML(place.id)}"><span>${escapeHTML(place.name)}</span><b>${escapeHTML(km)}</b><small>${escapeHTML(travel.walk==='UNKNOWN'?'Route pending':travel.walk+' walk'+(travel.drive!=='UNKNOWN'?' · '+travel.drive+' drive':''))}</small></button>`;}).join(''):''}</div><footer>${intelligence.precision==='AREA_ONLY'?'Around this area':'Around this home'} · ${routes.length?'modelled routes':'mapped places'}<small>Powered by Nexus Link</small></footer></article>`;
