function openTemporarySchedule(){if(!temporarySchedule)return;const start=temporarySchedule.date?new Date(temporarySchedule.date+'T12:00:00'):new Date(),days=temporarySchedule.window==='week'?Array.from({length:7},(_,index)=>{const date=new Date(start);date.setDate(date.getDate()+index);return date;}):[start];$('#tunnel-content').innerHTML=`<section class="tunnel-form temporary-schedule"><button class="drawer-close" type="button" data-close aria-label="Close">×</button><span>SMART SCHEDULING · TEMPORARY ${temporarySchedule.window.toUpperCase()} VIEW</span><h2 id="tunnel-title">Owner availability.</h2><p>${escapeHTML(temporarySchedule.property?.title||'Property enquiry')} · This page exists only for the current request and resets on reload.</p><div class="schedule-status">QR CONNECTION PENDING · The assigned 2906 team holds the request until the owner joins.</div><div class="schedule-days">${days.map(date=>`<article><strong>${date.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'})}</strong><div><button type="button">09:00</button><button type="button">12:00</button><button type="button">15:00</button><button type="button">18:00</button></div></article>`).join('')}</div><p class="tunnel-note">Slots shown here are a scheduling workspace, not confirmed owner availability. Confirmation appears only after the owner or assigned agent responds.</p></section>`;}
function distanceKm(a,b){const rad=value=>value*Math.PI/180,dLat=rad(b[1]-a[1]),dLng=rad(b[0]-a[0]),v=Math.sin(dLat/2)**2+Math.cos(rad(a[1]))*Math.cos(rad(b[1]))*Math.sin(dLng/2)**2;return 2*6371*Math.asin(Math.sqrt(Math.min(1,v)));}
function villagePlaces(name){const property=inventory.find(item=>item.area===name&&item.coordinates);if(!property)return {center:null,nearby:[]};const nearby=places.map(place=>({...place,distanceKm:distanceKm(property.coordinates,place.coordinates)})).filter(place=>place.distanceKm<=2).sort((a,b)=>a.distanceKm-b.distanceKm);return {center:property.coordinates,nearby};}
