async function load(){
 try{
  const [inventoryResponse,placesResponse,mobilityResponse,curationResponse,guidesResponse]=await Promise.all([
   fetch('/api/nexus/inventory',{cache:'no-store'}),
   fetch('/api/nexus/places',{cache:'no-store'}).catch(()=>null),
   fetch('/Link/mobility-observations.json',{cache:'no-store'}).catch(()=>null),
   fetch('/api/nexus/curation').catch(()=>null),
   fetch('/link-marketplace/locality-guides.json').catch(()=>null)
  ]);
  if(!inventoryResponse.ok)throw new Error('Live inventory unavailable');
  const payload=await inventoryResponse.json();if(payload?.meta?.firewall_leaks?.length)throw new Error('Inventory privacy check failed');
  const curation=curationResponse?.ok?await curationResponse.json().catch(()=>({})):{};const ranks=new Map((curation.properties||[]).map(p=>[p.id,p]));
  inventory=(payload.properties||[]).filter(raw=>raw.listable===true&&['available','available_confirmed','upcoming'].includes(raw.status)&&(raw.images||[]).length).map(raw=>normalizeProperty({...raw,...ranks.get(raw.id)}));
  if(placesResponse?.ok){const placePayload=await placesResponse.json(),categories={beach:'swimming',swimming:'swimming',gym:'gyms',outdoor_gym:'gyms',sport:'sports',restaurant:'restaurants',cafe:'restaurants',bar:'nightlife',nightclub:'nightlife',grocery:'shopping',supermarket:'shopping',convenience:'shopping',pharmacy:'shopping',medical:'shopping',healthcare:'shopping',atm:'shopping',shopping:'shopping',bus_stop:'transport',ferry:'transport',park:'parks',promenade:'promenades',wellness:'wellness'};places=(placePayload.records||[]).filter(place=>Array.isArray(place.coordinates)&&place.coordinates.every(Number.isFinite)).map(place=>({...place,category:place.category||categories[place.kind]||null}));}
  if(mobilityResponse?.ok){const mobilityPayload=await mobilityResponse.json();mobilityObservations=Array.isArray(mobilityPayload.observations)?mobilityPayload.observations:[];}
  if(guidesResponse?.ok)localityGuides=(await guidesResponse.json()).records||[];
  smartCache.clear();populatePlaces();filterInventory();const requested=new URLSearchParams(location.search).get('property'),property=requested&&inventory.find(item=>item.id===requested);if(property)openProperty(property);
 }catch(error){$('#skeleton-grid').hidden=true;$('#result-meta').textContent=error.message;$('#result-title').textContent='Nexus Housing is reconnecting.';}
}

